// Template parameter is a reference, preventing array-to-pointer decay
template<typename T>
void f(T& param);

// Template utility to deduce array size at compile time
template<typename T, std::size_t N>
constexpr std::size_t arraySize(T (&)[N]) noexcept {
    return N;
}

const char name[] = "Scott Meyers"; // type is const char[13]

f(name); // T is deduced as const char[13], param's type is const char(&)[13]

int keyVals[] = {1, 3, 7, 9}; // type is int[4]
std::size_t size = arraySize(keyVals); // N is deduced as 4, returns 4
